R=[{"h": "Ser o estar", "p": ["Los dos significan «to be». Ser dice qué o cómo es algo por naturaleza; estar dice dónde está o en qué estado se encuentra ahora.", "Pregunta útil: ¿es parte de lo que la cosa es, o es una situación?"]}, {"h": "Ser: identidad, origen, profesión, material, hora", "ex": [["Mi madre es profesora de instituto.", "tatoeba", "es", "My mother is a high school teacher."], ["Soy de la costa oeste.", "tatoeba", "Soy", "I'm from the West Coast."], ["El anillo es de oro puro.", "tatoeba", "es", "The ring is made of pure gold."], ["Son las dos de la tarde.", "tatoeba", "Son", "It's 2:00 p.m."], ["Ella es alta y bella.", "tatoeba", "es", "She's tall and beautiful."], ["vino a llamarla Dulcinea del Toboso, porque era natural del Toboso", "quijote", "era", null], ["Algunos dicen que es orgulloso; pero estoy bien segura de no haber notado nada de eso.", "orgullo", "es orgulloso", null], ["—La libertad, Sancho, es uno de los más preciosos dones que a los hombres dieron los cielos", "quijote", "es", null]]}, {"h": "Ser: dónde y cuándo ocurre un evento", "p": ["Para lugares de cosas usamos estar, pero para eventos (una fiesta, un concierto) usamos ser."], "ex": [["La fiesta es el lunes.", "tatoeba", "es", "The party's Monday."]]}, {"h": "Estar: lugar, estado, resultado", "ex": [["Él está en casa hoy.", "tatoeba", "está", "He is at home today."], ["Estoy cansada de oír eso.", "tatoeba", "Estoy", "I'm tired of hearing that."], ["La tienda está cerrada hoy.", "tatoeba", "está", "The shop is closed today."], ["El gato no está muerto.", "tatoeba", "está", "The cat is not dead."], ["Confuso estaba Roque, y no sabía qué hacerse.", "quijote", "estaba", null], ["Isabel estaba sorprendida, mas no dijo una palabra.", "orgullo", "estaba", null], ["Cardenio estaba en el mismo pensamiento, y el de Luscinda corría por la misma cuenta.", "quijote", "estaba", null]]}, {"h": "Estar + gerundio: lo que pasa ahora mismo", "ex": [["Estoy trabajando en otro caso.", "tatoeba", "Estoy trabajando", "I'm working on another case."], ["Hecho esto, con grandísimo silencio se entraron adonde él estaba durmiendo y descansando de las pasadas refriegas.", "quijote", "estaba durmiendo", null]]}, {"h": "Adjetivos que cambian de sentido", "p": ["ser listo = clever · estar listo = ready", "ser aburrido = boring · estar aburrido = bored", "ser rico = rich · estar rico = tasty", "ser loco = a madman · estar loco = to have gone mad (now)"], "ex": [["Se dice que es listo.", "tatoeba", "es listo", "It's said that he's clever."], ["Tom está listo para todo.", "tatoeba", "está listo", "Tom is ready for anything."], ["Pienso que su novela es aburrida.", "tatoeba", "es aburrida", "I think his novel is boring."], ["Ella está aburrida de esta novela.", "tatoeba", "está aburrida", "She is bored with this novel."], ["Él es rico y poderoso.", "tatoeba", "es rico", "He's rich and powerful."], ["—No es loco —respondió Sancho—, sino atrevido.", "quijote", "es loco", null], ["por donde conoció que su vecino estaba loco, y dábale priesa a llegar al pueblo", "quijote", "estaba loco", null]]}, {"h": "Pretérito o imperfecto", "p": ["Pretérito: una acción terminada, vista como un punto: ayer, una vez, de repente, y luego.", "Imperfecto: el fondo de la escena: descripción, costumbre, edad, hora, lo que estaba pasando.", "Truco: el imperfecto pinta el decorado; el pretérito cuenta lo que pasa en él."]}, {"h": "Pretérito: hechos terminados", "ex": [["Ayer vi a mis amigos.", "tatoeba", "vi", "I saw my friends yesterday."], ["Tom una vez trabajó en una panadería.", "tatoeba", "trabajó", "Tom once worked at a bakery."], ["Roma no fue construida en un día.", "tatoeba", "fue", "Rome wasn't built in a day."], ["Llegó la noche, y cenó el gobernador, con licencia del señor doctor Recio.", "quijote", "Llegó", null], ["Como con eso se terminó la conversación, Isabel abandonó la sala poco después.", "orgullo", "abandonó", null], ["Al mozo se le vinieron las lágrimas a los ojos, y no pudo responder palabra.", "quijote", "pudo", null]]}, {"h": "Imperfecto: fondo, costumbre, descripción", "ex": [["Era una noche oscura y sin luna.", "tatoeba", "Era", "It was a dark, moonless night."], ["Hacía calor en la habitación.", "tatoeba", "Hacía", "The room was hot."], ["Él tenía 19 años entonces.", "tatoeba", "tenía", "He was 19 at the time."], ["Antes había un castillo en la colina.", "tatoeba", "había", "There used to be a castle on the hill."], ["De niño podía nadar bien.", "tatoeba", "podía", "I could swim well when I was a boy."], ["El señor Hurst y Bingley jugaban al piquet, y la esposa del primero contemplaba la partida.", "orgullo", "jugaban", null], ["En un lugar de la Mancha, de cuyo nombre no quiero acordarme, no ha mucho tiempo que vivía un hidalgo de los de lanza en astillero, adarga antigua, rocín flaco y galgo corredor.", "quijote", "vivía", null]]}, {"h": "Los dos juntos: fondo + acción", "ex": [["No estaba allí cuando pasó.", "tatoeba", "estaba", "I wasn't there when it happened."], ["Todo estaba arreglado cuando yo llegué; así que mi curiosidad no se vió tan horriblemente atormentada como la tuya parece estarlo.", "orgullo", "llegué", null], ["Murió cuando tenía 54 años.", "tatoeba", "tenía", "She died when she was 54 years old."], ["En esto, descubrieron treinta o cuarenta molinos de viento que hay en aquel campo", "quijote", "descubrieron", null]]}, {"h": "Verbos que cambian de sentido en pretérito", "p": ["conocer: conocía = I knew · conocí = I met", "saber: sabía = I knew · supe = I found out", "querer: no quería = I didn’t want · no quise = I refused", "poder: podía = I was able · pude = I managed"], "ex": [["Ayer conocí a tu padre.", "tatoeba", "conocí", "I met your dad yesterday."], ["No sabía que era Tom.", "tatoeba", "sabía", "I didn't know it was Tom."], ["No quise herir a nadie.", "tatoeba", "quise", "I meant no harm."], ["No pude parar de reír.", "tatoeba", "pude", "I couldn't stop laughing."], ["El ventero, que no conocía a don Quijote, tan admirado le tenían sus locuras como su liberalidad.", "quijote", "conocía", null]]}, {"h": "Fue: de ser y de ir", "p": ["fui, fue, fueron... sirven para ser y para ir. El contexto decide. Por eso la app no te pregunta esas formas."], "ex": [["Fui a nadar al río.", "tatoeba", "Fui", "I went swimming in the river."], ["Todo esto fue un error.", "tatoeba", "fue", "This was all a mistake."]]}, {"h": "En el Perú: ustedes", "p": ["En el Perú y en toda América se usa ustedes para hablar con varias personas, con amigos o con desconocidos. El vosotros (habláis, erais, estuvisteis) es de España, y aparece mucho en el Quijote.", "La app acepta todas las personas, pero en la vida diaria peruana usarás ustedes."]}, {"h": "Leer Orgullo y prejuicio (1924)", "p": ["Es la traducción de José Jordán de Urríes y Azara, de 1924. Sigue la ortografía de entonces: fué, vió, dió llevaban acento (hoy fue, vio, dio). Isabel es Elizabeth, y Catalina es Kitty."], "ex": [["Isabel se vió obligada a salir.", "orgullo", "vió", null]]}, {"h": "Leer el Quijote", "p": ["El Quijote es de 1605. Algunas formas antiguas: deste = de este, della = de ella, dél = de él, mesmo = mismo, agora = ahora, vuestra merced = usted.", "El pronombre a veces va detrás del verbo: díjole = le dijo, preguntóle = le preguntó."], "ex": [["¿Qué padre o qué madre se dolerá della?", "quijote", "della", null], ["—¿Qué es lo que vuestra merced dice, señor?", "quijote", "vuestra merced", null], ["Díjole Sancho que mirase que era hora de comer.", "quijote", "Díjole", null]]}],
FIRST=[["En un lugar de la Mancha, de cuyo nombre no quiero acordarme, no ha mucho tiempo que vivía un hidalgo de los de lanza en astillero, adarga antigua, rocín flaco y galgo corredor.", "quijote", "vivía", null], ["Es verdad universalmente admitida que un soltero poseedor de buena fortuna tiene que necesitar una mujer.", "orgullo", "Es", null]];
